var VI_MAX = 9007199254740991; // Number.MAX_SAFE_INTEGER
function viZigzagEncode(n){
  if(n<0) return -2*n-1;
  return 2*n;
}
function viZigzagDecode(z){
  if(z%2===0) return z/2;
  return -(z+1)/2;
}
function viEncode(n){
  if(typeof n!=='number'||!isFinite(n)||Math.floor(n)!==n) return { value:null, error:'必须是整数' };
  if(n<0) return { value:null, error:'varint 不接受负数，请启用 ZigZag' };
  if(n>VI_MAX) return { value:null, error:'超出安全整数范围' };
  var out=[];
  while(n>=128){
    out.push((n%128)|0x80);
    n=Math.floor(n/128);
  }
  out.push(n);
  return { value:out, error:null };
}
function viDecodeOne(bytes, offset){
  var result=0, shift=1, i=offset||0;
  for(;;){
    if(i>=bytes.length) return { value:null, length:0, error:'字节流截断' };
    var b=bytes[i];
    result+=(b&0x7f)*shift;
    if(result>VI_MAX) return { value:null, length:0, error:'超出安全整数范围' };
    i++;
    if((b&0x80)===0) break;
    shift*=128;
  }
  return { value:result, length:i-(offset||0), error:null };
}
function viDecodeStream(bytes){
  var out=[], i=0;
  while(i<bytes.length){
    var r=viDecodeOne(bytes, i);
    if(r.error) return { value:null, error:r.error+' (offset '+i+')' };
    out.push(r.value); i+=r.length;
  }
  return { value:out, error:null };
}
function viHexToBytes(hex){
  var s=String(hex).replace(/[\s,]+/g,'').toLowerCase();
  if(s.length%2!==0) return { value:null, error:'hex 长度必须为偶数' };
  if(!/^[0-9a-f]*$/.test(s)) return { value:null, error:'非法 hex 字符' };
  var out=[];
  for(var i=0;i<s.length;i+=2) out.push(parseInt(s.substr(i,2),16));
  return { value:out, error:null };
}
function viBytesToHex(bytes){
  return bytes.map(function(b){ var h=b.toString(16); return h.length<2?'0'+h:h; }).join(' ');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { viZigzagEncode:viZigzagEncode, viZigzagDecode:viZigzagDecode,
    viEncode:viEncode, viDecodeOne:viDecodeOne, viDecodeStream:viDecodeStream,
    viHexToBytes:viHexToBytes, viBytesToHex:viBytesToHex };
}
if (typeof window !== 'undefined') {
  window.VarintForgePure = { viZigzagEncode:viZigzagEncode, viZigzagDecode:viZigzagDecode,
    viEncode:viEncode, viDecodeOne:viDecodeOne, viDecodeStream:viDecodeStream,
    viHexToBytes:viHexToBytes, viBytesToHex:viBytesToHex };
}
